it('returns policy-aware continuation after a ready Archive preview', () => {
    const state = {
      name: 'ready-change',
      phase: 'archive',
      revision: 4,
    } as NativeChangeState;
    const preflightHash = 'a'.repeat(64);

    expect(
      nativeContinuation({
        state,
        archiveReady: true,
        archiveConfirmation: 'automatic',
        archivePreflightHash: preflightHash,
      }),
    ).toMatchObject({
      disposition: 'continue',
      action: 'archive',
      command: `comet native archive ready-change --expect-preflight ${preflightHash}`,
      commandArgs: [
        'comet',
        'native',
        'archive',
        'ready-change',
        '--expect-preflight',
        preflightHash,
      ],
      requiresUserDecision: false,
      requiredInputs: [],
    });
    expect(
      nativeContinuation({
        state,
        archiveReady: true,
        archiveConfirmation: 'required',
        archivePreflightHash: preflightHash,
      }),
    ).toMatchObject({
      disposition: 'await-user',
      action: 'archive',
      command: null,
      commandArgs: [
        'comet',
        'native',
        'archive',
        'ready-change',
        '--expect-preflight',
        preflightHash,
        '--confirmed',
      ],
      requiresUserDecision: true,
      requiredInputs: ['archive-confirmation'],
      inputOptions: [
        expect.objectContaining({
          input: 'archive-confirmation',
          flags: ['--confirmed'],
          choices: ['confirm', 'keep-active'],
        }),
      ],
    });
  })

